#### 5️⃣ `.github/workflows/ci.yml` - CI流程（Skill自动运行）

```yaml
name: CI Pipeline

on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main, develop ]

jobs:
  # 🔴 S1：需求分类（如果有需求更新）
  classify-requirements:
    runs-on: ubuntu-latest
    if: contains(github.event.head_commit.message, '[requirement]')
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "S1: Classify requirements"
        run: npm run skill:s1:classify

  # 🔴 S3：CodeReview预审（每个PR自动运行）
  code-review:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
        with:
          fetch-depth: 0  # 获取全部历史，用于diff
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "S3: Code Review Analysis"
        run: npm run skill:s3:cr
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

  # 🔴 S4：配置检查（关键！防止白屏）
  check-config:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "S4: Check Configuration"
        run: npm run skill:s4:check-config
      # 【重要】如果配置检查失败，整个CI流程停止
      - name: "CI failed due to config issues"
        if: failure()
        run: exit 1

  # 单元测试
  test:
    runs-on: ubuntu-latest
    needs: [code-review, check-config]  # 等待S3和S4通过
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "Install dependencies"
        run: npm install
      - name: "Run tests"
        run: npm test -- --coverage
      - name: "Upload coverage"
        uses: codecov/codecov-action@v3

  # 代码规范检查
  lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "Install dependencies"
        run: npm install
      - name: "Lint"
        run: npm run lint

  # 构建检查
  build:
    runs-on: ubuntu-latest
    needs: [code-review, check-config, test, lint]
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "Install dependencies"
        run: npm install
      - name: "Build"
        run: npm run build
```

