#### 5️⃣ `.github/workflows/ci.yml` - CI流程（Skill自动运行）

```yaml
name: CI Pipeline

on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main, develop ]

jobs:
  # 🔴 S1：需求分类（如果有需求更新）
  classify-requirements:
    runs-on: ubuntu-latest
    if: contains(github.event.head_commit.message, '[requirement]')
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "S1: Classify requirements"
        run: npm run skill:s1:classify

  # 🔴 S3：CodeReview预审（每个PR自动运行）
  code-review:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
        with:
          fetch-depth: 0  # 获取全部历史，用于diff
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "S3: Code Review Analysis"
        run: npm run skill:s3:cr
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

  # 🔴 S4：配置检查（关键！防止白屏）
  check-config:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "S4: Check Configuration"
        run: npm run skill:s4:check-config
      # 【重要】如果配置检查失败，整个CI流程停止
      - name: "CI failed due to config issues"
        if: failure()
        run: exit 1

  # 单元测试
  test:
    runs-on: ubuntu-latest
    needs: [code-review, check-config]  # 等待S3和S4通过
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "Install dependencies"
        run: npm install
      - name: "Run tests"
        run: npm test -- --coverage
      - name: "Upload coverage"
        uses: codecov/codecov-action@v3

  # 代码规范检查
  lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "Install dependencies"
        run: npm install
      - name: "Lint"
        run: npm run lint

  # 构建检查
  build:
    runs-on: ubuntu-latest
    needs: [code-review, check-config, test, lint]
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "Install dependencies"
        run: npm install
      - name: "Build"
        run: npm run build
```

#### 6️⃣ `.github/workflows/cd.yml` - CD流程（发版自动化）

```yaml
name: CD Pipeline

on:
  push:
    branches: [ main ]
    tags: [ 'v*' ]

jobs:
  # 🔴 S4：最终配置检查（发版前必须通过）
  final-config-check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "S4: Final Configuration Check"
        run: npm run skill:s4:check-config
        env:
          STRICT_MODE: 'true'  # 严格模式，任何警告都会中止
      - name: "Deployment blocked due to config issues"
        if: failure()
        run: |
          echo "❌ 发版被阻止：配置检查失败"
          exit 1

  # 部署到测试环境
  deploy-staging:
    runs-on: ubuntu-latest
    needs: [final-config-check]
    environment:
      name: staging
      url: https://staging.example.com
    steps:
      - uses: actions/checkout@v3
      - name: "Deploy to staging"
        run: |
          # 部署脚本
          bash scripts/deploy.sh staging

  # 🔴 S6：冒烟测试（发版前自动验证）
  smoke-tests:
    runs-on: ubuntu-latest
    needs: [deploy-staging]
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
        with:
          node-version: '18'
      - name: "S6: Smoke Tests"
        run: npm run skill:s6:smoke-test
        env:
          TEST_ENV: 'staging'
      - name: "Upload test report"
        if: always()
        uses: actions/upload-artifact@v3
        with:
          name: smoke-test-report
          path: reports/smoke-test.json

  # 部署到生产环境
  deploy-production:
    runs-on: ubuntu-latest
    needs: [smoke-tests]
    environment:
      name: production
      url: https://example.com
    steps:
      - uses: actions/checkout@v3
      - name: "Deploy to production"
        run: |
          bash scripts/deploy.sh production

  # 监控告警（部署后）
  monitor:
    runs-on: ubuntu-latest
    if: always()
    needs: [deploy-production]
    steps:
      - name: "Monitor deployed service"
        run: |
          # 监控脚本
          curl -f https://example.com/health || exit 1
```

